#include <vector>
#include <queue>

class Solution {
public:
    int minTime(int n, std::vector<std::vector<int>>& edges) {
        std::vector<std::vector<std::pair<int, int>>> adj(n);
        for (const auto& e : edges) {
            adj[e[0]].push_back({e[1], e[2]});
        }

        std::vector<long long> dist(n, 1e18);
        dist[0] = 0;
        using P = std::pair<long long, int>;
        std::priority_queue<P, std::vector<P>, std::greater<P>> pq;
        pq.push({0, 0});

        while (!pq.empty()) {
            auto [curr_time, u] = pq.top();
            pq.pop();

            if (u == n - 1) return curr_time;
            if (curr_time > dist[u]) continue;

            for (const auto& [v, w] : adj[u]) {
                if (curr_time + w < dist[v]) {
                    dist[v] = curr_time + w;
                    pq.push({dist[v], v});
                }
            }
        }

        return dist[n - 1] >= 1e18 ? -1 : dist[n - 1];
    }
};

import java.util.*;

class Solution {
    public int minTime(int n, int[][] edges) {
        List<List<int[]>> adj = new ArrayList<>(n);
        for (int i = 0; i < n; i++) adj.add(new ArrayList<>());
        for (int[] e : edges) {
            adj.get(e[0]).add(new int[]{e[1], e[2]});
        }

        long[] dist = new long[n];
        Arrays.fill(dist, Long.MAX_VALUE);
        dist[0] = 0;

        PriorityQueue<long[]> pq = new PriorityQueue<>(Comparator.comparingLong(a -> a[0]));
        pq.add(new long[]{0, 0});

        while (!pq.isEmpty()) {
            long[] top = pq.poll();
            long currTime = top[0];
            int u = (int) top[1];

            if (u == n - 1) return (int) currTime;
            if (currTime > dist[u]) continue;

            for (int[] edge : adj.get(u)) {
                int v = edge[0], w = edge[1];
                if (currTime + w < dist[v]) {
                    dist[v] = currTime + w;
                    pq.add(new long[]{dist[v], v});
                }
            }
        }

        return dist[n - 1] == Long.MAX_VALUE ? -1 : (int) dist[n - 1];
    }
}

/**
 * @param {number} n
 * @param {number[][]} edges
 * @return {number}
 */
var minTime = function(n, edges) {
    const adj = Array.from({ length: n }, () => []);
    for (const [u, v, w] of edges) {
        adj[u].push([v, w]);
    }

    const dist = new Float64Array(n).fill(Infinity);
    dist[0] = 0;

    const heap = [[0, 0]];

    while (heap.length > 0) {
        heap.sort((a, b) => a[0] - b[0]);
        const [currTime, u] = heap.shift();

        if (u === n - 1) return currTime;
        if (currTime > dist[u]) continue;

        for (const [v, w] of adj[u]) {
            if (currTime + w < dist[v]) {
                dist[v] = currTime + w;
                heap.push([dist[v], v]);
            }
        }
    }

    return dist[n - 1] === Infinity ? -1 : dist[n - 1];
};
